function renderSearchModal(){if(logType==='memory')logType='movie';searchController?.abort();searchSequence++;$('#log-content').innerHTML=modalHead('Add to shelf','Search for a title, or add an item yourself.')+`<div class="modal-body"><div class="type-picker" role="group" aria-label="What are you logging?">${Object.keys(TYPES).map(t=>`<button data-log-type="${t}" class="${logType===t?'active':''}" aria-pressed="${logType===t}">${TYPES[t]}</button>`).join('')}</div><form id="catalog-search" class="modal-search">${icon('search')}<label class="sr-only" for="catalog-query">Search ${TYPES[logType].toLowerCase()}</label><input id="catalog-query" type="search" minlength="2" maxlength="200" required placeholder="${{movie:'A film that stayed with you…',tv:'Find a show…',anime:'Find an anime…',book:'A title or an author…',album:'An album or an artist…',restaurant:'Restaurant name and city…',place:'A place, landmark, or city…'}[logType]}"><button class="button primary small" type="submit">Search</button></form><p class="source-hint">Searches ${providerName[logType]}. Select a result to keep its cover and details.</p><div id="catalog-results" class="search-results"></div><div class="manual-entry"><span>Some things aren’t in a catalog.</span><button class="text-button" data-action="manual">Add it yourself ${icon('arrow')}</button></div></div>`;}
